'use strict';
const upgradeExperience=n=>10*n*n+50*n+150;
function cultivationBudget(from,to,existing){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to>25||to<from)throw Error('请输入 0–25 的整数等级，目标等级不能低于当前等级。');if(!Number.isInteger(existing)||existing<0||(from<25&&existing>=upgradeExperience(from))||(from===25&&existing!==0))throw Error('已有经验须为当前等级内的非负整数，且小于升下一级所需经验；25级请填0。');let total=0;for(let n=from;n<to;n++)total+=upgradeExperience(n);return Math.max(0,total-existing)}
function humanBudget(from,to,existing,price,count){const exp=cultivationBudget(from,to,existing),clicks=Math.ceil(exp/10);return{exp,clicks,cost:clicks*price,materials:clicks*5,total:clicks*price*count,threshold:to*150}}
function petBudget(from,to,existing,price,count,daily){const exp=cultivationBudget(from,to,existing),fruit=Math.ceil(exp/150);return{exp,fruit,totalFruit:fruit*count,cost:fruit*price*count,overflow:fruit*150-exp,days:Math.ceil(fruit/daily)}}
if(typeof module!=='undefined')module.exports={cultivationBudget,humanBudget,petBudget};
if(typeof document!=='undefined'){
const el=id=>document.getElementById(id),value=id=>Number(el(id).value),format=n=>n.toLocaleString('zh-CN',{maximumFractionDigits:2});
function field(id,integer,min,max){if(el(id).value.trim()==='')throw Error('请填完整所有输入项。');const n=value(id);if(!Number.isFinite(n)||n<min||n>max||(integer&&!Number.isInteger(n)))throw Error('请检查数量、单价与等级范围；等级和数量须为整数。');return n}
const result=(number,label)=>'<div class="result"><strong>'+number+'</strong><span>'+label+'</span></div>';
function updateHuman(){try{['h-from','h-to'].forEach(id=>field(id,true,0,25));field('h-exp',true,0,100000);const count=field('h-count',true,1,5),price=field('h-price',false,1,1e9);const r=humanBudget(value('h-from'),value('h-to'),value('h-exp'),price,count);el('h-error').textContent='';el('h-results').innerHTML=result(format(r.exp),'单角色剩余修炼经验')+result(format(r.cost/10000)+' 万','单角色总金钱需求')+result(format(r.total/10000)+' 万',count+' 个角色总金钱需求')+result(format(r.clicks),'单角色点修次数（每次10经验）')+result(format(r.materials),'单角色资材需求（有资材模式）')+result(format(r.threshold),'单角色帮贡总数参考门槛，非消耗')}catch(e){el('h-error').textContent=e.message;el('h-results').innerHTML=''}}
function updatePet(){try{['p-from','p-to'].forEach(id=>field(id,true,0,25));field('p-exp',true,0,100000);const count=field('p-count',true,1,5),price=field('p-price',false,0,1e6),daily=field('p-daily',true,1,10);const r=petBudget(value('p-from'),value('p-to'),value('p-exp'),price,count,daily);el('p-error').textContent='';el('p-results').innerHTML=result(format(r.exp),'单角色剩余宠修经验')+result(format(r.fruit)+' 个','单角色修炼果数量')+result(format(r.totalFruit)+' 个',count+' 个角色共需修炼果')+result(format(r.cost)+' 万','全部角色购买预算')+result(format(r.overflow),'单角色理论经验结余')+result(format(r.days)+' 天','各角色同步食用的预计天数')}catch(e){el('p-error').textContent=e.message;el('p-results').innerHTML=''}}
el('h-type').addEventListener('change',()=>{el('h-price').value=el('h-type').value;updateHuman()});document.querySelectorAll('#human-calc input').forEach(e=>e.addEventListener('input',updateHuman));document.querySelectorAll('#pet-calc input').forEach(e=>e.addEventListener('input',updatePet));updateHuman();updatePet();
let done=false;try{done=localStorage.getItem('lesson2-complete')==='1'}catch{}const button=el('complete');const paint=()=>button.textContent=done?'第二课已学完 ✓ · 点击重置':'标记第二课已学完 ✓';paint();button.onclick=()=>{done=!done;try{localStorage.setItem('lesson2-complete',done?'1':'0')}catch{}paint()};
const sections=[...document.querySelectorAll('section')];function scrollUpdate(){const p=Math.min(100,Math.round(window.scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)*100));el('progress').value=p;el('progress-label').textContent='阅读进度 '+p+'%';let current=sections[0].id;sections.forEach(s=>{if(s.getBoundingClientRect().top<innerHeight*.35)current=s.id});document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+current))}addEventListener('scroll',scrollUpdate,{passive:true});scrollUpdate();
}
